#!/usr/bin/env python3
"""Generates the Entity State golden fixtures (M6 WI-13) independently of the Rust codec.

Every field is placed at an explicit byte offset taken from the Entity State PDU table of
IEEE Std 1278.1-2012 (version 7) and IEEE Std 1278.1a-1998 (version 6), with python's `struct`
(big-endian). A second, separate encoding of the whole PDU with one `struct` format string is
compared byte for byte with the first, so a mistaken offset shows up here and not in the Rust tests.
The values are exactly representable binary fractions, so the Rust tests compare floats with `==`.

Usage: python3 gen_es.py   (writes v6/es_*.hex and v7/es_*.hex next to this file)
"""
import os
import struct

HERE = os.path.dirname(os.path.abspath(__file__))

# Entity State PDU fixed part, version 7 and version 6 alike (header offsets 0..11, body 12..143).
# (offset, struct format, field name); the value comes from the scenario dict below.
FIELDS = [
    (0, ">B", "protocol_version"),
    (1, ">B", "exercise_id"),
    (2, ">B", "pdu_type"),
    (3, ">B", "protocol_family"),
    (4, ">I", "timestamp"),
    (8, ">H", "length"),
    (10, ">B", "pdu_status (v7) / padding (v6)"),
    (11, ">B", "padding"),
    (12, ">H", "entity_id.site"),
    (14, ">H", "entity_id.application"),
    (16, ">H", "entity_id.entity"),
    (18, ">B", "force_id"),
    (19, ">B", "number_of_articulation_parameters"),
    (20, ">B", "entity_type.kind"),
    (21, ">B", "entity_type.domain"),
    (22, ">H", "entity_type.country"),
    (24, ">B", "entity_type.category"),
    (25, ">B", "entity_type.subcategory"),
    (26, ">B", "entity_type.specific"),
    (27, ">B", "entity_type.extra"),
    (28, ">B", "alt_entity_type.kind"),
    (29, ">B", "alt_entity_type.domain"),
    (30, ">H", "alt_entity_type.country"),
    (32, ">B", "alt_entity_type.category"),
    (33, ">B", "alt_entity_type.subcategory"),
    (34, ">B", "alt_entity_type.specific"),
    (35, ">B", "alt_entity_type.extra"),
    (36, ">f", "linear_velocity.x"),
    (40, ">f", "linear_velocity.y"),
    (44, ">f", "linear_velocity.z"),
    (48, ">d", "location.x"),
    (56, ">d", "location.y"),
    (64, ">d", "location.z"),
    (72, ">f", "orientation.psi"),
    (76, ">f", "orientation.theta"),
    (80, ">f", "orientation.phi"),
    (84, ">I", "appearance"),
    (88, ">B", "dr.algorithm"),
    (89, ">15s", "dr.other_parameters"),
    (104, ">f", "dr.linear_acceleration.x"),
    (108, ">f", "dr.linear_acceleration.y"),
    (112, ">f", "dr.linear_acceleration.z"),
    (116, ">f", "dr.angular_velocity.x"),
    (120, ">f", "dr.angular_velocity.y"),
    (124, ">f", "dr.angular_velocity.z"),
    (128, ">B", "marking.character_set"),
    (129, ">11s", "marking.characters"),
    (140, ">I", "capabilities"),
]

# The same table as one format string (second, independent encoding).
WHOLE = ">BBBB I H BB HHH BB BBHBBBB BBHBBBB fff ddd fff I B 15s fff fff B 11s I".replace(" ", "")

BASIC = {
    "exercise_id": 1, "timestamp": 0x01020304, "status": 0,
    "site": 1, "app": 2, "ent": 3, "force": 1, "articulations": 0,
    "type": (1, 2, 225, 3, 4, 5, 6), "alt": (1, 2, 222, 7, 8, 9, 10),
    "vel": (10.5, -2.25, 0.75), "loc": (3900000.5, 1100000.25, 4800000.125),
    "ori": (0.5, 0.25, -0.125), "appearance": 0x0021B2C3, "drm": 2,
    "other": bytes(range(1, 16)), "acc": (0.5, 1.5, -0.25), "angvel": (0.375, 0.0625, 0.125),
    "charset": 1, "marking": b"T72-01", "capabilities": 0x0A0B0C0D,
}


def values(s, version, length):
    status = s["status"] if version == 7 else 0
    return [
        version, s["exercise_id"], 1, 1, s["timestamp"], length, status, 0,
        s["site"], s["app"], s["ent"], s["force"], s["articulations"],
        *s["type"], *s["alt"], *s["vel"], *s["loc"], *s["ori"], s["appearance"], s["drm"],
        s["other"], *s["acc"], *s["angvel"], s["charset"], s["marking"].ljust(11, b"\0"),
        s["capabilities"],
    ]


def build(s, version):
    n = s["articulations"]
    length = 144 + 16 * n
    vals = values(s, version, length)
    buf = bytearray(length)
    for (off, fmt, _name), v in zip(FIELDS, vals):
        struct.pack_into(fmt, buf, off, v)
    # Independent cross-check with the whole-PDU format.
    whole = struct.pack(WHOLE, *vals)
    assert whole == bytes(buf[:144]), "offset table and whole-PDU format disagree"
    assert struct.calcsize(WHOLE) == 144
    for i in range(n):  # articulation parameters: 16 opaque bytes each
        buf[144 + 16 * i:160 + 16 * i] = bytes(0xA0 + 16 * i + j for j in range(16))
    return bytes(buf), vals


def write(name, s, version, note):
    data, vals = build(s, version)
    lines = [
        f"# {name} ({'v7, IEEE 1278.1-2012' if version == 7 else 'v6, IEEE 1278.1a-1998'}): {note}",
        "# Generated by gen_es.py from the standard's field table; see README.md.",
        "# format: <hex bytes>  # <offset> <field> = <value>",
    ]
    for (off, fmt, fname), v in zip(FIELDS, vals):
        size = struct.calcsize(fmt)
        hexs = data[off:off + size].hex(" ")
        lines.append(f"{hexs:<48} # {off} {fname} = {v!r}")
    for i in range(s["articulations"]):
        off = 144 + 16 * i
        lines.append(f"{data[off:off + 16].hex(' '):<48} # {off} articulation_parameter[{i}] (opaque) ")
    path = os.path.join(HERE, f"v{version}", f"{name}.hex")
    with open(path, "w") as f:
        f.write("\n".join(lines) + "\n")


def scenarios():
    yield "es_basic", dict(BASIC), "Land platform, DRM 2, marking padded", None
    yield "es_status", {**BASIC, "status": 0x0B}, "v7 PDU status 0x0B (TEI, LVC 1, CEI) (v6 has no status; no v6 file)", 7
    yield "es_deactivated", {**BASIC, "appearance": 0x00A1B2C3}, "appearance bit 23 set (deactivated)", None
    yield "es_zero_type", {**BASIC, "type": (0,) * 7, "alt": (0,) * 7}, "all-zero entity types", None
    yield "es_marking_full", {**BASIC, "marking": b"ABCDEFGHIJK"}, "11 marking characters, no padding", None
    yield "es_articulated", {**BASIC, "articulations": 2}, "2 articulation parameters (decode only)", None
    for code in range(10):
        yield f"es_drm_{code}", {**BASIC, "drm": code}, f"dead reckoning algorithm {code}", None


if __name__ == "__main__":
    for name, s, note, only in scenarios():
        for version in (7, 6):
            if only is None or only == version:
                write(name, s, version, note)
    print("ok")
